//! Where the desk service lives, for the clients that call it: its config
//! dir, data dir, token file, port and base URL — the one copy
//! `embarch-api` (and, in `tasks/ui/130`, `embarch-ui`) reads instead of
//! each spelling out `embarch-desk`'s `paths.rs` again. The desk keeps its own
//! rule; this is the clients' copy of it, as `token_discovery` is for Core's
//! token. `embarch-desk` does not depend on this crate (api decision 151).
//!
//! **Reads, never creates.** The token is generated by the desk on first
//! read; a client that finds no file treats the desk as not running.

use anyhow::{Context, Result};
use std::ffi::OsString;
use std::path::PathBuf;

/// The desk's port when `EMBARCH_DESK_PORT` is unset or not a `u16`.
pub const DESK_DEFAULT_PORT: u16 = 4891;

/// The token file's name inside the config dir.
pub const DESK_TOKEN_FILE: &str = "desk-token";

type Env<'a> = &'a dyn Fn(&str) -> Option<OsString>;

fn process_env(key: &str) -> Option<OsString> {
    std::env::var_os(key)
}

fn home(env: Env) -> Result<PathBuf> {
    env("HOME").filter(|h| !h.is_empty()).map(PathBuf::from).context("HOME is not set")
}

/// `own` taken as the folder itself, else `$xdg/embarch-desk` (an empty
/// value reads as unset), else `$HOME/<fallback>/embarch-desk`.
fn dir(env: Env, own: &str, xdg: &str, fallback: &[&str]) -> Result<PathBuf> {
    if let Some(d) = env(own) {
        return Ok(PathBuf::from(d));
    }
    let base = match env(xdg).filter(|s| !s.is_empty()) {
        Some(x) => PathBuf::from(x),
        None => fallback.iter().fold(home(env)?, |p, part| p.join(part)),
    };
    Ok(base.join("embarch-desk"))
}

fn config_dir_in(env: Env) -> Result<PathBuf> {
    dir(env, "EMBARCH_DESK_CONFIG_DIR", "XDG_CONFIG_HOME", &[".config"])
}

fn data_dir_in(env: Env) -> Result<PathBuf> {
    dir(env, "EMBARCH_DESK_DATA_DIR", "XDG_DATA_HOME", &[".local", "share"])
}

fn port_in(env: Env) -> u16 {
    env("EMBARCH_DESK_PORT").and_then(|p| p.to_str().and_then(|p| p.parse().ok())).unwrap_or(DESK_DEFAULT_PORT)
}

/// The desk's config dir: `EMBARCH_DESK_CONFIG_DIR`, else
/// `$XDG_CONFIG_HOME/embarch-desk`, else `$HOME/.config/embarch-desk`.
pub fn config_dir() -> Result<PathBuf> {
    config_dir_in(&process_env)
}

/// The desk's data dir: `EMBARCH_DESK_DATA_DIR`, else
/// `$XDG_DATA_HOME/embarch-desk`, else `$HOME/.local/share/embarch-desk`.
pub fn data_dir() -> Result<PathBuf> {
    data_dir_in(&process_env)
}

/// The file holding the bearer every caller of the desk presents.
pub fn token_path() -> Result<PathBuf> {
    Ok(config_dir()?.join(DESK_TOKEN_FILE))
}

/// The desk's port: `EMBARCH_DESK_PORT` as a `u16`, else 4891.
pub fn port() -> u16 {
    port_in(&process_env)
}

/// `http://127.0.0.1:<port>`.
pub fn base_url() -> String {
    format!("http://127.0.0.1:{}", port())
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashMap;

    /// An environment the test owns, so no test races another over the
    /// process's.
    fn with<R>(vars: &[(&str, &str)], f: impl FnOnce(Env) -> R) -> R {
        let m: HashMap<String, OsString> = vars.iter().map(|(k, v)| (k.to_string(), OsString::from(v))).collect();
        f(&|k| m.get(k).cloned())
    }

    #[test]
    fn config_dir_takes_its_own_variable_as_the_folder_itself() {
        let got = with(&[("EMBARCH_DESK_CONFIG_DIR", "/x/c"), ("XDG_CONFIG_HOME", "/xdg"), ("HOME", "/h")], config_dir_in).unwrap();
        assert_eq!(got, PathBuf::from("/x/c"));
    }

    #[test]
    fn config_dir_falls_to_xdg_then_home() {
        assert_eq!(with(&[("XDG_CONFIG_HOME", "/xdg"), ("HOME", "/h")], config_dir_in).unwrap(), PathBuf::from("/xdg/embarch-desk"));
        assert_eq!(with(&[("HOME", "/h")], config_dir_in).unwrap(), PathBuf::from("/h/.config/embarch-desk"));
    }

    #[test]
    fn an_empty_xdg_reads_as_unset() {
        assert_eq!(with(&[("XDG_CONFIG_HOME", ""), ("HOME", "/h")], config_dir_in).unwrap(), PathBuf::from("/h/.config/embarch-desk"));
        assert_eq!(with(&[("XDG_DATA_HOME", ""), ("HOME", "/h")], data_dir_in).unwrap(), PathBuf::from("/h/.local/share/embarch-desk"));
    }

    #[test]
    fn data_dir_follows_the_same_three_steps() {
        assert_eq!(with(&[("EMBARCH_DESK_DATA_DIR", "/x/d"), ("XDG_DATA_HOME", "/xdg"), ("HOME", "/h")], data_dir_in).unwrap(), PathBuf::from("/x/d"));
        assert_eq!(with(&[("XDG_DATA_HOME", "/xdg"), ("HOME", "/h")], data_dir_in).unwrap(), PathBuf::from("/xdg/embarch-desk"));
        assert_eq!(with(&[("HOME", "/h")], data_dir_in).unwrap(), PathBuf::from("/h/.local/share/embarch-desk"));
    }

    #[test]
    fn no_home_and_nothing_else_is_an_error_and_an_empty_home_is_unset() {
        assert!(with(&[], config_dir_in).is_err());
        assert!(with(&[("HOME", "")], data_dir_in).is_err());
        assert!(with(&[("HOME", "")], |e| config_dir_in(e)).is_err());
        // An override needs no HOME.
        assert!(with(&[("EMBARCH_DESK_DATA_DIR", "/d")], data_dir_in).is_ok());
    }

    #[test]
    fn port_is_the_variable_else_the_default_and_junk_is_the_default() {
        assert_eq!(with(&[("EMBARCH_DESK_PORT", "5000")], port_in), 5000);
        assert_eq!(with(&[], port_in), DESK_DEFAULT_PORT);
        assert_eq!(with(&[("EMBARCH_DESK_PORT", "abc")], port_in), DESK_DEFAULT_PORT);
        assert_eq!(with(&[("EMBARCH_DESK_PORT", "70000")], port_in), DESK_DEFAULT_PORT);
        assert_eq!(with(&[("EMBARCH_DESK_PORT", "")], port_in), DESK_DEFAULT_PORT);
    }

    #[test]
    fn token_file_and_base_url_follow_the_dir_and_port() {
        let p = with(&[("EMBARCH_DESK_CONFIG_DIR", "/c")], config_dir_in).unwrap().join(DESK_TOKEN_FILE);
        assert_eq!(p, PathBuf::from("/c/desk-token"));
        assert_eq!(format!("http://127.0.0.1:{}", with(&[("EMBARCH_DESK_PORT", "9")], port_in)), "http://127.0.0.1:9");
    }
}
